use crate::{plugins::{self as p,Result},app::AppState};
use serde_json::{Value,json};use std::{sync::{Arc,Mutex,atomic::{AtomicUsize,Ordering}},fs,io::Read};use tauri::{WebviewWindow,State,Emitter};use tauri_plugin_dialog::DialogExt;
type Data<'a>=State<'a,Arc<AppState>>;
static METRICS:Mutex<Option<Value>>=Mutex::new(None);static FETCHES:AtomicUsize=AtomicUsize::new(0);
pub fn metrics_requested(data:&AppState)->bool{p::list(&data.directory).unwrap_or_default().iter().any(|i|i.enabled&&i.manifest["permissions"]["systemMetrics"]==true)}
pub fn cache_metrics(v:Value){if let Ok(mut m)=METRICS.lock(){*m=Some(v)}}
fn gate(w:&WebviewWindow,read:bool)->Result<()>{if p::trusted_window_label(w.label(),read){Ok(())}else{Err("Untrusted plugin command caller".into())}}
fn event(a:&tauri::AppHandle){let _=a.emit("plugins-changed",());}
fn active(d:&AppState,id:&str)->Result<p::Installed>{let i=p::installed(&d.directory,id)?;if !i.enabled{return Err("Plugin disabled".into())}Ok(i)}
#[tauri::command]pub fn plugin_list(window:WebviewWindow,data:Data<'_>)->Result<Vec<p::Installed>>{gate(&window,true)?;let _l=p::LOCK.lock().map_err(|_|"Plugin lock")?;p::list(&data.directory)}
#[tauri::command]pub async fn plugin_preview(window:WebviewWindow,data:Data<'_>,url:Option<String>,path:Option<String>,sha256:Option<String>,expected_id:Option<String>)->Result<Value>{gate(&window,false)?;let dir=data.directory.clone();tauri::async_runtime::spawn_blocking(move||{let(source,bytes)=match(url,path){(Some(u),None)=>{let b=p::download(&u,p::MAX_PACKAGE,None)?.2;(u,b)},(None,Some(s))=>{let f=fs::File::open(&s).map_err(|e|e.to_string())?;let mut b=vec![];f.take(p::MAX_PACKAGE as u64+1).read_to_end(&mut b).map_err(|e|e.to_string())?;(s,b)},_=>return Err("Choose exactly one URL or local package".into())};if let Some(id)=expected_id{if p::validate_package(&bytes)?.0["id"]!=id{return Err("Package ID differs from catalog or update".into())}}let _l=p::LOCK.lock().map_err(|_|"Plugin lock")?;p::preview(&dir,&bytes,&source,sha256.as_deref())}).await.map_err(|e|e.to_string())?}
#[tauri::command]pub fn plugin_install(app:tauri::AppHandle,window:WebviewWindow,data:Data<'_>,token:String)->Result<p::Installed>{gate(&window,false)?;let _l=p::LOCK.lock().map_err(|_|"Plugin lock")?;let i=p::commit(&data.directory,&token)?;event(&app);Ok(i)}
#[tauri::command]pub fn plugin_enable(app:tauri::AppHandle,window:WebviewWindow,data:Data<'_>,id:String,enabled:bool)->Result<()>{gate(&window,false)?;let _l=p::LOCK.lock().map_err(|_|"Plugin lock")?;let mut items=p::list(&data.directory)?;let theme=p::installed(&data.directory,&id)?.manifest["type"]=="theme";for i in &mut items{if i.manifest["id"]==id{i.enabled=enabled}else if enabled&&theme&&i.manifest["type"]=="theme"{i.enabled=false}}p::save(&data.directory,&items)?;event(&app);Ok(())}
#[tauri::command]pub fn plugin_uninstall(app:tauri::AppHandle,window:WebviewWindow,data:Data<'_>,id:String,remove_data:bool)->Result<()>{gate(&window,false)?;let _l=p::LOCK.lock().map_err(|_|"Plugin lock")?;p::installed(&data.directory,&id)?;let mut items=p::list(&data.directory)?;items.retain(|i|i.manifest["id"]!=id);p::save(&data.directory,&items)?;event(&app);let path=p::root(&data.directory).join("installed").join(&id);if path.exists(){fs::remove_dir_all(path).map_err(|e|e.to_string())?}if remove_data{let path=p::root(&data.directory).join("data").join(&id);if path.exists(){fs::remove_dir_all(path).map_err(|e|e.to_string())?}}Ok(())}
#[tauri::command]pub async fn plugin_catalog(window:WebviewWindow,url:Option<String>)->Result<Value>{gate(&window,false)?;tauri::async_runtime::spawn_blocking(move||{let b=p::download(url.as_deref().unwrap_or("https://47.85.175.203/catalog.json"),1024*1024,None)?.2;let v:Value=serde_json::from_slice(&b).map_err(|e|e.to_string())?;if v["schemaVersion"]!=1||!v["entries"].is_array(){return Err("Invalid catalog".into())}if v["entries"].as_array().unwrap().len()>512{return Err("Catalog too large".into())}for i in v["entries"].as_array().unwrap(){for k in ["id","name","author","type","version","url","sha256"]{if i[k].as_str().is_none_or(|s|s.len()>2048){return Err("Invalid catalog entry".into())}}p::https(i["url"].as_str().unwrap())?;p::version(i["version"].as_str().unwrap())?;}Ok(v)}).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn plugin_check_update(window:WebviewWindow,data:Data<'_>,id:String)->Result<Value>{gate(&window,false)?;let item=p::installed(&data.directory,&id)?;tauri::async_runtime::spawn_blocking(move||{let v:Value=if let Some(u)=item.manifest["updateUrl"].as_str(){serde_json::from_slice(&p::download(u,64*1024,None)?.2).map_err(|e|e.to_string())?}else{let catalog:Value=serde_json::from_slice(&p::download("https://47.85.175.203/catalog.json",1024*1024,None)?.2).map_err(|e|e.to_string())?;if catalog["schemaVersion"]!=1{return Err("Invalid catalog".into())}let Some(entry)=catalog["entries"].as_array().ok_or("Invalid catalog")?.iter().find(|e|e["id"]==id).cloned()else{return Ok(Value::Null)};entry};if v["id"]!=id{return Err("Update ID mismatch".into())}let ver=p::version(v["version"].as_str().ok_or("Missing update version")?)?;p::https(v["url"].as_str().ok_or("Missing update URL")?)?;if v["sha256"].as_str().is_none_or(|s|s.len()!=64||!s.bytes().all(|c|c.is_ascii_hexdigit())){return Err("Missing update SHA256".into())}if ver<=p::version(item.manifest["version"].as_str().unwrap())?{return Ok(Value::Null)}Ok(v)}).await.map_err(|e|e.to_string())?}
#[tauri::command]pub fn plugin_settings(window:WebviewWindow,data:Data<'_>,id:String,value:Option<Value>)->Result<Value>{gate(&window,false)?;let _l=p::LOCK.lock().map_err(|_|"Plugin lock")?;active(&data,&id)?;let path=p::root(&data.directory).join("data").join(id).join("settings.json");if let Some(v)=value{let b=serde_json::to_vec(&v).map_err(|e|e.to_string())?;if b.len()>256*1024{return Err("Settings exceed 256 KiB".into())}fs::create_dir_all(path.parent().unwrap()).map_err(|e|e.to_string())?;let tmp=path.with_extension("tmp");fs::write(&tmp,b).map_err(|e|e.to_string())?;fs::rename(tmp,&path).map_err(|e|e.to_string())?;}match fs::read(path){Ok(b)=>serde_json::from_slice(&b).map_err(|e|e.to_string()),Err(e)if e.kind()==std::io::ErrorKind::NotFound=>Ok(json!({})),Err(e)=>Err(e.to_string())}}
#[tauri::command]pub async fn plugin_fetch(window:WebviewWindow,data:Data<'_>,id:String,url:String)->Result<Value>{gate(&window,false)?;let i=active(&data,&id)?;let origins=i.manifest["permissions"]["network"].as_array().map(|a|a.iter().filter_map(|s|s.as_str().map(str::to_owned)).collect::<Vec<_>>()).unwrap_or_default();if FETCHES.fetch_add(1,Ordering::SeqCst)>=4{FETCHES.fetch_sub(1,Ordering::SeqCst);return Err("Plugin fetch concurrency limit".into())}tauri::async_runtime::spawn_blocking(move||{struct Guard;impl Drop for Guard{fn drop(&mut self){FETCHES.fetch_sub(1,Ordering::SeqCst);}}let _g=Guard;let(status,ct,b)=p::download(&url,1024*1024,Some(&origins))?;let body=String::from_utf8(b).map_err(|_|"Only UTF-8 network responses supported")?;Ok(json!({"status":status,"body":body,"contentType":ct}))}).await.map_err(|e|e.to_string())?}
#[tauri::command]pub fn plugin_metrics(window:WebviewWindow,data:Data<'_>,id:String)->Result<Value>{gate(&window,false)?;let i=active(&data,&id)?;if i.manifest["permissions"]["systemMetrics"]!=true{return Err("Metrics permission not granted".into())}Ok(METRICS.lock().map_err(|_|"Metrics lock")?.clone().unwrap_or(json!({})))}
#[tauri::command]pub async fn plugin_pick_file(app:tauri::AppHandle,window:WebviewWindow)->Result<Option<String>>{gate(&window,false)?;tauri::async_runtime::spawn_blocking(move||Ok(app.dialog().file().add_filter("DeskBox plugin",&["deskbox-plugin"]).blocking_pick_file().map(|f|f.to_string()))).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn plugin_bundle(window:WebviewWindow,data:Data<'_>,id:String)->Result<Value>{gate(&window,true)?;crate::plugin_guard::ensure(&window).await?;let _l=p::LOCK.lock().map_err(|_|"Plugin lock")?;let item=active(&data,&id)?;let dir=p::root(&data.directory).join("installed").join(&id);let mut resources=serde_json::Map::new();fn walk(dir:&std::path::Path,base:&std::path::Path,out:&mut serde_json::Map<String,Value>)->Result<()>{use base64::Engine;for e in fs::read_dir(dir).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;if e.file_type().map_err(|e|e.to_string())?.is_dir(){walk(&e.path(),base,out)?}else{let path=e.path();let rel=path.strip_prefix(base).unwrap().to_string_lossy().replace('\\',"/");let mime=match path.extension().and_then(|s|s.to_str()).unwrap_or("").to_ascii_lowercase().as_str(){"js"=>"text/javascript","css"=>"text/css","svg"=>"image/svg+xml","png"=>"image/png","webp"=>"image/webp","gif"=>"image/gif","jpg"|"jpeg"=>"image/jpeg","woff2"=>"font/woff2","html"=>"text/html",_=>"application/octet-stream"};let b=fs::read(path).map_err(|e|e.to_string())?;out.insert(rel,json!(format!("data:{mime};base64,{}",base64::engine::general_purpose::STANDARD.encode(b))));}}Ok(())}walk(&dir,&dir,&mut resources)?;let mut result=json!({"manifest":item.manifest,"resources":resources});if result["manifest"]["type"]=="theme"{result["theme"]=serde_json::from_slice(&fs::read(dir.join("theme.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if let Some(name)=result["theme"]["backgroundImage"].as_str().map(str::to_owned){result["theme"]["backgroundImage"]=result["resources"][name].clone();}}else{result["html"]=fs::read_to_string(dir.join(result["manifest"]["entry"].as_str().unwrap())).map_err(|e|e.to_string())?.into()}Ok(result)}
#[tauri::command]pub fn plugin_create_widget(app:tauri::AppHandle,window:WebviewWindow,data:Data<'_>,plugin_id:String,position:Option<Value>)->Result<String>{gate(&window,false)?;let i=active(&data,&plugin_id)?;if i.manifest["type"]!="widget"{return Err("Not a widget plugin".into())}let id=uuid::Uuid::new_v4().to_string();let pos=position.unwrap_or(json!({}));let origin=pos["x"].as_f64().zip(pos["y"].as_f64()).filter(|(x,y)|x.is_finite()&&y.is_finite()).map(|(x,y)|[x,y]);let(monitor,point,size)=data.location(origin)?;let x=point[0].clamp(0.,(size[0]-280.).max(0.));let y=point[1].clamp(0.,(size[1]-180.).max(0.));data.mutate(|c|{let mut style=crate::model::Style::new();style.insert("widgetData".into(),json!({"pluginId":plugin_id}));c.widgets.push(crate::model::Widget{id:id.clone(),kind:"plugin".into(),x,y,monitor,style});Ok(())})?;data.publish(&app)?;Ok(id)}
